#!/bin/sh
# stage1 = FPC-hosted compiler output (run/); stage2 = stage1 image run on cdcemu; stage3 = stage2 image run on cdcemu
# The runtime is CDC machine code (runtime.asm, generated by mkrt.py); the emulator is a pure CPU + 5 I/O words.
set -e
cd "$(dirname "$0")"
gcc -O2 -o cdcemu cdcemu.c -lm
python3 mkrt.py runtime.asm && python3 cdcasm.py runtime.asm runtime.img
mkdir -p stage2 stage3
python3 pasclgo2img.py run/pasclgo.out run/parmlist.out stage2/in.img --compiler
./cdcemu runtime.img stage2/in.img -i pascal.cdc -o stage2/listing.txt -d stage2 -m stage2/mem.img
python3 memparm.py stage2/mem.img 2048 stage2/parmlist.out
python3 pasclgo2img.py stage2/pasclgo.out stage2/parmlist.out stage3/in.img --compiler
./cdcemu runtime.img stage3/in.img -i pascal.cdc -o stage3/listing.txt -d stage3 -m stage3/mem.img
python3 memparm.py stage3/mem.img 2048 stage3/parmlist.out
cmp run/pasclgo.out stage2/pasclgo.out && cmp run/parmlist.out stage2/parmlist.out
cmp stage2/pasclgo.out stage3/pasclgo.out && cmp stage2/listing.txt stage3/listing.txt && cmp stage2/parmlist.out stage3/parmlist.out
echo "SELF-HOSTING FIXED POINT: stage1 == stage2 == stage3"
